 for(const side of [-1,1])for(let z=-14;z<8;z+=5){box(worldScene,side*7.35,1.7,z,.95,3.4,1.15,stoneA);box(worldScene,side*7.35,3.5,z,.0+1.35,.35,1.55,stoneB);}
 box(worldScene,0,4.2,-16,18,.65,1.2,stoneB);box(worldScene,0,3.5,-16,9,.5,.5,stoneA);
 // carved stone ribs, altar debris, and brazier flames
 for(const side of [-1,1])for(let z=-12;z<8;z+=5){const flame=new THREE.Mesh(new THREE.IcosahedronGeometry(.15,1),torchMat);flame.position.set(side*6.2,2.15,z);worldScene.add(flame);const light=new THREE.PointLight(0xff8134,18,6,2);light.position.set(side*6.2,2.3,z);worldScene.add(light);ambientFlames.push({mesh:flame,light,seed:Math.random()*6});box(worldScene,side*6.2,1.35,z,.26,.7,.26,stoneB);const bowl=new THREE.Mesh(new THREE.CylinderGeometry(.25,.16,.12,8),trimStone);bowl.position.set(side*6.2,1.72,z);worldScene.add(bowl);}
 for(let i=0;i<11;i++){const rubble=box(worldScene,(Math.random()-.5)*12,.12,-13+Math.random()*18,.18+Math.random()*.38,.25,.22+Math.random()*.4,stoneA);rubble.rotation.y=Math.random()*2;}
 // distant archway sigil
