 for(let i=0;i<8;i++){const a=i*Math.PI/4,rune=new THREE.Mesh(new THREE.BoxGeometry(.12,.025,.32),runeMat);rune.position.set(Math.cos(a)*1.02,.015,Math.sin(a)*1.02-4.1);rune.rotation.y=-a;worldScene.add(rune)}
